package com.nigson.integration.notification;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.Problem;
import com.nigson.shared.problem.ProblemCode;
import tools.jackson.databind.JsonNode;
/** Ephemeral rendering envelope: destination and variables never enter logs or provider response DTOs. */
public final class StaffReplyMessage {
 public record Request(String phone,String contentSid,Map<String,String> variables,String callback,String hash){public Request{variables=Map.copyOf(variables);}@Override public String toString(){return "StaffReplyRequest[protected]";}}
 private final String callback;private final StaffReplyCrypto crypto;
 public StaffReplyMessage(String env,String callback,StaffReplyCrypto crypto){if(callback==null||callback.length()>2048)throw new IllegalArgumentException("STAFF_REPLY_CALLBACK_REQUIRED");var u=URI.create(callback);if(u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!"/api/v1/webhooks/notifications/twilio/status".equals(u.getPath()))throw new IllegalArgumentException("STAFF_REPLY_CALLBACK_REQUIRED");if(Set.of("local","test").contains(env)){if(!"http".equals(u.getScheme())||!Set.of("localhost","127.0.0.1","commerce").contains(u.getHost()))throw new IllegalArgumentException("STAFF_REPLY_LOCAL_CALLBACK_REQUIRED");}else if(!"https".equals(u.getScheme())||u.getPort()!=-1)throw new IllegalArgumentException("STAFF_REPLY_PUBLIC_CALLBACK_REQUIRED");this.callback=callback;this.crypto=Objects.requireNonNull(crypto);}
 public Request build(StaffReplyExecution.Claim claim){try{String phone=new String(crypto.decrypt(claim.id(),"RECIPIENT",claim.recipientCiphertext()),StandardCharsets.UTF_8);if(!phone.matches("\\+234[1-9][0-9]{9}")||claim.accountHash()==null||!claim.accountHash().matches("[a-f0-9]{64}"))throw invalid();byte[] raw=crypto.decrypt(claim.id(),"VARIABLES",claim.variablesCiphertext());JsonNode varsNode=EventCodec.JSON.readTree(raw);if(!varsNode.isObject()||varsNode.size()>20)throw invalid();var variables=new TreeMap<String,String>();for(var field:varsNode.properties()){if(!field.getKey().matches("[A-Za-z0-9_]{1,40}")||!field.getValue().isString()||field.getValue().asString().length()>1000||field.getValue().asString().codePoints().anyMatch(Character::isISOControl))throw invalid();variables.put(field.getKey(),field.getValue().asString());}JsonNode template=claim.template(),schema=template.path("variablesSchema");validate(template,schema,variables);String sid=template.path("providerTemplateId").asString();String target=callback+"?jobId="+claim.id();var identity=EventCodec.JSON.createObjectNode();identity.put("v",1).put("jobId",claim.id().toString()).put("accountHash",claim.accountHash()).put("templateHash",EventCodec.hash(template)).put("phone",phone).put("contentSid",sid).put("callback",target);identity.set("variables",EventCodec.JSON.valueToTree(variables));return new Request(phone,sid,variables,target,crypto.requestHash(EventCodec.JSON.writeValueAsBytes(identity)));}catch(Problem.Failure safe){throw safe;}catch(RuntimeException malformed){throw invalid();}}
 private static void validate(JsonNode t,JsonNode schema,Map<String,String> vars){if(!t.isObject()||!t.propertyNames().equals(Set.of("id","code","revision","locale","channel","classification","body","providerTemplateId","variablesSchema"))||!"STAFF_LEAD_REPLY".equals(t.path("code").asString())||!"WHATSAPP".equals(t.path("channel").asString())||!"TRANSACTIONAL".equals(t.path("classification").asString())||!t.path("providerTemplateId").asString().matches("HX[a-fA-F0-9]{32}")||!schema.isObject()||!"object".equals(schema.path("type").asString())||!schema.path("additionalProperties").isBoolean()||schema.path("additionalProperties").asBoolean()||!schema.path("properties").isObject()||!schema.path("required").isArray())throw invalid();var props=schema.path("properties");var required=new HashSet<String>();for(JsonNode item:schema.path("required")){if(!item.isString()||!required.add(item.asString()))throw invalid();}if(!props.propertyNames().containsAll(required)||!props.propertyNames().containsAll(vars.keySet())||!vars.keySet().containsAll(required))throw invalid();for(var field:props.properties()){JsonNode rule=field.getValue();if(!rule.isObject()||!"string".equals(rule.path("type").asString())||!rule.path("maxLength").isIntegralNumber()||!rule.path("maxLength").canConvertToInt()||rule.path("maxLength").asInt()<1||rule.path("maxLength").asInt()>1000)throw invalid();String value=vars.get(field.getKey());if(value!=null&&value.length()>rule.path("maxLength").asInt())throw invalid();}}
 private static Problem.Failure invalid(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
}
